import{_ as a,o,c as t,a2 as d}from"./chunks/framework.CiKk3sJz.js";const u=JSON.parse('{"title":"漫画 · 第 40 话 details 与 summary 进阶：原生折叠面板","description":"","frontmatter":{},"headers":[],"relativePath":"comics/html/EP.40-details-advanced.md","filePath":"comics/html/EP.40-details-advanced.md","lastUpdated":1792579602000}'),l={name:"comics/html/EP.40-details-advanced.md"};function c(i,e,s,r,n,h){return o(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="漫画-·-第-40-话-details-与-summary-进阶-原生折叠面板" tabindex="-1">漫画 · 第 40 话 details 与 summary 进阶：原生折叠面板 <a class="header-anchor" href="#漫画-·-第-40-话-details-与-summary-进阶-原生折叠面板" aria-label="Permalink to &quot;漫画 · 第 40 话 details 与 summary 进阶：原生折叠面板&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/html/14-details-advanced">docs/html/14-details-advanced.md</a> ｜ 原画：<a href="./EP.40-details-advanced.svg">EP.40-details-advanced.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话苦主。为 FAQ 页引了 15KB 的 accordion 组件库，互斥逻辑手写 JS，高度动画靠 JS 算 scrollHeight，键盘和屏幕阅读器支持全靠库赏饭，SSR hydration 还闪动。</li><li><strong>标签君</strong>：HTML5 结构师，掏出原生双件套——<code>&lt;details&gt;</code>/<code>&lt;summary&gt;</code> 零 JS 折叠，再加进阶三件套：<code>name</code> 互斥、<code>::details-content</code> 动画、<code>interpolate-size</code> 开关。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>像素酱被「折叠面板必引库」的思维定式困住：包体积 +15KB、互斥手写、动画手写、可访问性全靠库。标签君翻开 HTML 规范——<code>&lt;details&gt;</code> 天生支持键盘与屏幕阅读器，<code>open</code> 属性 SSR 友好；相同 <code>name</code> 的 details 自动互斥，一行 JS 不用写；<code>::details-content</code> 伪元素配合 <code>interpolate-size: allow-keywords</code>，<code>height: auto</code> 平滑过渡终于原生可用。像素酱发现连 View Transitions 都能和 toggle 事件配合出丝滑快照补间。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>组件库方案的隐性成本：包体积、JS 互斥逻辑、JS 高度动画、SSR 闪动、可访问性外包。每一个都是原生两行 HTML 就能解决的事。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p><code>&lt;details open&gt;</code> + <code>&lt;summary&gt;</code> 就是完整折叠面板，键盘/读屏天然支持。进阶三件套：<code>name=&quot;faq&quot;</code> 让同组 details 互斥（同时只开一个）；<code>::details-content</code> 选中内容容器做动画；<code>interpolate-size: allow-keywords</code> 是 <code>height: auto</code> 可过渡的关键开关。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>四大场景：FAQ 手风琴（name 互斥零 JS）、平滑动画（<code>::details-content</code> 过渡高度与透明度）、自定义标记（<code>list-style: none</code> + <code>::after</code> 换 +/-）、与 View Transitions 配合（toggle 事件里 <code>startViewTransition</code>）。记住边界：<strong><code>&lt;summary&gt;</code> 必须是第一个子元素</strong>；name 互斥组不提交表单数据。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li><code>&lt;summary&gt;</code> 必须是第一个子元素；open 属性控制默认展开，SSR 友好。</li><li>相同 name 的 details 自动互斥；<code>::details-content</code> 实现 height 平滑过渡。</li><li><code>interpolate-size: allow-keywords</code> 是 height: auto 过渡的关键开关。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么给 <code>::details-content</code> 写了 <code>transition: height .3s</code> 却没有动画效果？</p><p><strong>答</strong>：因为 <code>height</code> 在收起态是 <code>0</code>、展开态是 <code>auto</code>——<code>auto</code> 是关键字，默认不可插值。需要在 <code>:root</code>（或祖先）声明 <code>interpolate-size: allow-keywords</code> 解锁关键字插值，过渡才会生效。该特性 Chrome 129+ 支持，旧浏览器回退为瞬时展开（渐进增强，功能无损）。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>基础折叠 + name 互斥手风琴 + <code>::details-content</code> 高度动画 + View Transitions 配合：<a href="./../../examples/html/14-details-advanced/index-01-details-advanced.html">examples/html/14-details-advanced/</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 41 话《@container 进阶》——style queries 按容器样式查样式、容器查询单位 cqw/cqi 免算百分比、与 @scope 组合拳，组件真正「装哪美哪」。</p>',22)])])}const p=a(l,[["render",c]]);export{u as __pageData,p as default};
